export const SW = "const C='fueldrop-shell-v15';const HOME='/functions/v1/fueldrop';\nself.addEventListener('install',e=>{e.waitUntil(caches.open(C).then(c=>c.addAll([HOME,HOME+'?asset=manifest',HOME+'?asset=icon'])).then(()=>self.skipWaiting()))});\nself.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(x=>x!==C).map(x=>caches.delete(x)))).then(()=>self.clients.claim()))});\nself.addEventListener('push',e=>{let d={};try{d=e.data?e.data.json():{}}catch{d={body:e.data?e.data.text():'Fuel prices updated'}};const title=d.title||'FillMeNow';const o={body:d.body||'Your best-value fuel update is ready.',icon:HOME+'?asset=icon',badge:HOME+'?asset=icon',tag:d.tag||'fueldrop',renotify:true,data:d.data||{},actions:[{action:'open',title:'Open FillMeNow'}]};e.waitUntil(self.registration.showNotification(title,o))});\nself.addEventListener('notificationclick',e=>{e.notification.close();e.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(cs=>{for(const c of cs){if('focus'in c&&c.url.includes('/functions/v1/fueldrop'))return c.focus()}return clients.openWindow(HOME)}))});\nself.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;const u=new URL(e.request.url);if(u.searchParams.has('api')){e.respondWith(fetch(e.request));return}e.respondWith(fetch(e.request).then(r=>{if(r.ok&&u.origin===location.origin)caches.open(C).then(c=>c.put(e.request,r.clone()));return r}).catch(()=>caches.match(e.request).then(r=>r||caches.match(HOME))))})";
